/* ============================================================
   Conductor — Design System
   styles/base.css
   ============================================================ */

/* --- Tokens --- */
:root {
    --bg-primary: #0f1923;
    --bg-darker: #0a1219;
    --bg-card-1: #1a2e44;
    --bg-card-2: #162436;
    --bg-elevated: #1e3a5f;

    --text-primary: #e0e6ed;
    --text-secondary: #c0cad6;
    --text-body: #b0bec5;
    --text-muted: #94a3b8;
    --text-label: #7a8a9e;
    --text-dim: #5a6a7e;
    --text-faint: #3a4a5e;
    --text-date: #4a5a6e;

    --accent-blue: #38bdf8;
    --accent-blue-dark: #2ea8d8;
    --accent-blue-hover: #0ea5e9;
    --accent-green: #4ade80;
    --accent-green-dark: #22c55e;
    --accent-amber: #fb923c;
    --accent-amber-dark: #d97706;
    --accent-red: #f87171;
    --accent-red-dark: #dc2626;
    --accent-purple: #a78bfa;
    --accent-gold: #fbbf24;
    --accent-slate: #64748b;

    --border-subtle: rgba(255,255,255,0.04);
    --border-light: rgba(255,255,255,0.06);
    --border-medium: rgba(255,255,255,0.08);
    --border-strong: rgba(255,255,255,0.1);
    --border-input: rgba(255,255,255,0.12);
    --border-focus: var(--accent-blue);

    --card-gradient: linear-gradient(135deg, var(--bg-card-1), var(--bg-card-2));
    --card-radius: 12px;
    --card-padding: 20px 24px;

    --font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
    --font-mono: Consolas, 'Courier New', monospace;
}


/* --- Reset --- */
*, *::before, *::after {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: var(--font-family);
    background: var(--bg-primary);
    color: var(--text-primary);
    min-height: 100vh;
    line-height: 1.5;
}


/* --- Typography --- */
h1 {
    font-size: 1.8rem;
    font-weight: 300;
    color: #fff;
    text-align: center;
    letter-spacing: 0.04em;
}

h2 { font-size: 1.4rem; font-weight: 400; color: #fff; }
h3 { font-size: 1.1rem; font-weight: 600; color: #fff; }

.subtitle {
    text-align: center;
    font-size: 0.9rem;
    color: var(--text-label);
    margin: 6px 0 6px;
}

.section-title {
    font-size: 1.1rem;
    font-weight: 600;
    color: #fff;
    margin: 32px 0 16px;
    padding-bottom: 8px;
    border-bottom: 1px solid var(--border-medium);
}

p.body {
    font-size: 0.88rem;
    color: var(--text-body);
    line-height: 1.8;
    margin-bottom: 16px;

